'use strict';
const $ = id => document.getElementById(id), api = window.desktopApp, t = (key,values) => window.I18n.t(key,values);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = value => structuredClone(value);
const state = {page:'library', view:'overview', language:'en', library:[], selected:null, work:null, schemas:{}, paths:{}, version:'', busy:false, search:'',profile:'all',sex:'all',favorites:false,sort:'recent',geneSearch:'',category:'all',changed:false,unknown:false,codeSource:'current',codeFormat:'encoded',codeDraft:null,conversion:null,target:'none',targetFormat:'encoded',lossy:false,game:null,prepared:'',compatibility:null,compatKey:'',gameBusy:false,gameMessage:'',pathsBusy:false};
let newDraft=null, detectTimer, detectRevision=0, encodeTimer, encodeRevision=0, pollTimer, pollInFlight=false, compatRevision=0, toastTimer, portraitTarget='new', confirmResolve=null;
const portraits = new Map(),closedGeneGroups=new Set(),paletteCache=new Map();
let geneEditSession=null,paletteState=null;
const icon=name=>window.StudioIcons?.icon(name)||'';
let contextMenu=null,toastSource='';
function closeContextMenu(){contextMenu?.remove();contextMenu=null;}
function showContextMenu(id,x,y){closeContextMenu();const entry=state.library.find(e=>e.id===id);if(!entry)return;state.selected=id;renderLibrary();const menu=document.createElement('div');menu.className='context-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label',t('actionsFor',{name:entry.name}));menu.innerHTML=btn('open-entry','openEditor','',`data-id="${id}" role="menuitem"`)+btn('prepare-entry','prepare','',`data-id="${id}" role="menuitem" ${entry.format==='original'?'disabled':''}`)+btn('open-original','openOriginal','',`data-id="${id}" role="menuitem"`)+btn('copy-entry-original','copyOriginal','',`data-id="${id}" role="menuitem"`)+btn('copy-entry-current','copyCurrent','',`data-id="${id}" role="menuitem"`)+btn('duplicate-entry','duplicate','',`data-id="${id}" role="menuitem"`)+btn('export-entry','export','',`data-id="${id}" role="menuitem"`)+btn('delete-entry','delete','danger',`data-id="${id}" role="menuitem"`);document.body.appendChild(menu);contextMenu=menu;const bounds=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,innerWidth-bounds.width-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-bounds.height-8))+'px';menu.querySelector('button')?.focus();}

function profile(value){return ({none:'Vanilla',epe:'EPE',agot:'AGOT'})[value]||t('unknown');}
function format(value){return t(['encoded','ruler_designer'].includes(value)?value:'unverified');}
function sex(value){return t(['female','male'].includes(value)?value:'unspecified');}
function btn(action,key,cls='',extra=''){return `<button type="button" data-action="${action}" class="${cls}" ${extra}>${esc(t(key))}</button>`;}
function option(value,label,selected){return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;}
function profileOptions(selected,all=false){return (all?option('all',t('allProfiles'),selected):'')+['none','epe','agot'].map(x=>option(x,profile(x),selected)).join('');}
function sexOptions(selected,all=false){return (all?option('all',t('allSexes'),selected):'')+['unspecified','female','male'].map(x=>option(x,sex(x),selected)).join('');}
function field(label,control,cls=''){return `<label class="field ${cls}"><span>${esc(t(label))}</span>${control}</label>`;}
function check(id,key,value){return `<label class="check"><input id="${id}" type="checkbox" ${value?'checked':''}>${esc(t(key))}</label>`;}
function date(value){return value?new Date(value).toLocaleDateString(window.I18n.locale,{year:'numeric',month:'short',day:'numeric'}):'–';}
function changedGenes(w=state.work){return w?.genes.filter(g=>JSON.stringify(g.values)!==JSON.stringify(w.baseline[g.name])).length||0;}
function dirty(w=state.work){return !!w && (w.dirty || !w.savedId || state.codeDraft!==null);}
function toast(message,error=false){toastSource=message;const node=$('toast');node.textContent=t(message);node.className='toast'+(error?' error':'');node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{node.hidden=true;},error?9000:3500);}
async function run(action){if(state.busy)return;state.busy=true;document.body.classList.add('saving-lock');const surfaces=[...document.body.children].filter(n=>n.id!=='confirmDialog'&&n.id!=='toast').map(n=>[n,n.inert]);const fields=[...document.querySelectorAll('input,select,textarea')].map(n=>[n,n.disabled]);for(const [n] of surfaces)n.inert=true;for(const [n] of fields)n.disabled=true;try{return await action();}catch(e){toast(e.message||'failed',true);}finally{state.busy=false;for(const [n,previous] of surfaces)n.inert=previous;for(const [n,previous] of fields)if(n.isConnected)n.disabled=previous;document.body.classList.remove('saving-lock');}}
function renderChrome(){if(!$('toast').hidden)$('toast').textContent=t(toastSource);
 $('brandSubtitle').textContent=t('subtitle');$('languageLabel').textContent=t('language');$('languageSelect').value=window.I18n.language;$('languageSelect').setAttribute('aria-label',t('language'));$('newLabel').textContent=t('newDna');if($('localLabel'))$('localLabel').hidden=true;if($('sidebarCount'))$('sidebarCount').hidden=true;document.querySelector('.sidebar-bottom')?.setAttribute('hidden','');
 $('mainNav').innerHTML=[['library','library-big'],['edit','dna'],['connection','network'],['settings','settings']].map(([page,icon])=>`<button class="nav-button ${state.page===page?'active':''}" data-action="navigate" data-page="${page}" ${state.page===page?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${window.StudioIcons?.icon(icon)||''}</span><span>${esc(t(page))}</span>${page==='edit'&&state.work?'<span class="nav-dot"></span>':''}</button>`).join('');
}
function render(){renderChrome();if(state.page==='library')renderLibrary();else if(state.page==='edit')renderEditor();else if(state.page==='connection')renderConnection();else renderSettings();}
function navigate(page){state.page=page;render();clearTimeout(pollTimer);if(page==='connection')pollGame();}
function heading(key,intro,actions=''){return `<div class="page-heading"><div><h2>${esc(t(key))}</h2><p>${esc(t(intro))}</p></div><div class="actions">${actions}</div></div>`;}
function empty(title,help,actions){return `<div class="empty-state"><img class="empty-emblem" src="../../assets/background-emblem.png" alt=""><h3>${esc(t(title))}</h3><p>${esc(t(help))}</p><div class="actions">${actions}</div></div>`;}
function portraitHtml(entry,large=false){const url=entry?.portrait?.dataUrl||portraits.get(entry?.id)?.dataUrl;return url?`<img class="${large?'portrait-large':'tile-portrait'}" src="${esc(url)}" alt="${esc(t('currentPortrait'))}" ${entry.id?`data-portrait="${esc(entry.id)}"`:''}>`:`<div class="${large?'portrait-large':'tile-portrait'} portrait-placeholder" ${entry?.id?`data-portrait="${esc(entry.id)}"`:''}>${esc((entry?.name||'?').trim().charAt(0).toUpperCase())}</div>`;}
function hydratePortraits(){for(const e of state.library){if(!e.thumbnail||portraits.has(e.id))continue;portraits.set(e.id,null);api.libraryPortrait(e.id).then(p=>{if(!p)return;portraits.set(e.id,p);for(const node of document.querySelectorAll('[data-portrait]')){if(node.dataset.portrait!==e.id)continue;const img=document.createElement('img');img.className=node.className.replace(' portrait-placeholder','');img.dataset.portrait=e.id;img.src=p.dataUrl;img.alt=t('currentPortrait');node.replaceWith(img);}}).catch(()=>{});}}
function renderLibrary(){
 let entries=state.library.filter(e=>(!state.search||`${e.name} ${e.note}`.toLowerCase().includes(state.search.toLowerCase()))&&(state.profile==='all'||e.profile===state.profile)&&(state.sex==='all'||(e.sex||'unspecified')===state.sex)&&(!state.favorites||e.favorite));entries.sort(state.sort==='name'?(a,b)=>a.name.localeCompare(b.name):['female','male'].includes(state.sort)?(a,b)=>{const rank=e=>(e.sex||'unspecified')===state.sort?0:(e.sex==='unspecified'||!e.sex?2:1);return rank(a)-rank(b)||a.name.localeCompare(b.name);}:(a,b)=>b.updatedAt.localeCompare(a.updatedAt));
 const selected=state.library.find(e=>e.id===state.selected);
 $('main').innerHTML=heading('library','libraryIntro',btn('library-import','import')+btn('library-export','exportAll','ghost'))+`<div class="filters"><input id="librarySearch" type="search" aria-label="${esc(t('searchLibrary'))}" placeholder="${esc(t('searchLibrary'))}" value="${esc(state.search)}"><select id="libraryProfile" aria-label="${esc(t('profile'))}">${profileOptions(state.profile,true)+option('unknown',t('unverified'),state.profile)}</select><select id="librarySex" aria-label="${esc(t('sex'))}">${sexOptions(state.sex,true)}</select>${check('libraryFavorites','favorites',state.favorites)}<select id="librarySort" aria-label="${esc(t('recent'))}">${option('recent',t('recent'),state.sort)+option('name',t('nameAZ'),state.sort)+option('female',t('femaleFirst'),state.sort)+option('male',t('maleFirst'),state.sort)}</select></div>`+(state.library.length?`<div class="count-label">${entries.length} / ${state.library.length}</div><div class="library-layout"><div class="library-list">${entries.length?entries.map(e=>`<button class="character-tile ${e.id===state.selected?'selected':''}" data-action="select-entry" data-id="${e.id}" aria-pressed="${e.id===state.selected}">${portraitHtml(e)}<span class="tile-copy"><strong>${e.favorite?'★ ':''}${esc(e.name)}</strong><span>${esc(profile(e.profile))} · ${esc(sex(e.sex))}</span><small>${esc(e.note||format(e.format))}</small></span></button>`).join(''):`<div class="empty-small">${esc(t('noMatches'))}<p>${btn('clear-filters','clearFilters','ghost')}</p></div>`}</div><section class="library-detail" id="libraryDetail">${selected?libraryDetail(selected):`<div class="empty-small">${esc(t('selectEntry'))}</div>`}</section></div>`:empty('emptyLibrary','emptyLibraryHelp',btn('new','newDna','primary')+btn('library-import','import')));hydratePortraits();
}
function libraryDetail(e){return `<div class="detail-top">${portraitHtml(e)}<div><h3>${esc(e.name)}</h3><div class="badge-line"><span class="tag">${esc(profile(e.profile))}</span>${e.format==='original'?`<span class="tag warn">${esc(t('unverified'))}</span>`:''}<span class="tag muted">${esc(sex(e.sex))}</span></div></div></div><div class="actions">${btn('open-entry','openEditor','primary',`data-id="${e.id}"`)}${btn('prepare-entry','prepare','',`data-id="${e.id}" ${e.format==='original'?'disabled':''}`)}</div><p class="note-text">${esc(e.note||t('noNote'))}</p><dl class="metadata"><dt>${esc(t('format'))}</dt><dd>${esc(format(e.format))}</dd><dt>${esc(t('sourceProfile'))}</dt><dd>${esc(profile(e.sourceProfile))}</dd><dt>${esc(t('updated'))}</dt><dd>${esc(date(e.updatedAt))}</dd></dl><div class="detail-actions">${btn('copy-entry-current','copyCurrent','small',`data-id="${e.id}"`)}${btn('copy-entry-original','copyOriginal','small',`data-id="${e.id}"`)}${btn('favorite-entry',e.favorite?'unfavorite':'favorite','small',`data-id="${e.id}"`)}${btn('duplicate-entry','duplicate','small',`data-id="${e.id}"`)}${btn('export-entry','export','small',`data-id="${e.id}"`)}${btn('metadata-entry','editMetadata','small',`data-id="${e.id}"`)}${btn('portrait-entry','chooseImage','small',`data-id="${e.id}"`)}${btn('delete-entry','delete','small ghost danger',`data-id="${e.id}"`)}</div><details><summary>${esc(t('details'))}</summary><dl class="metadata"><dt>${esc(t('created'))}</dt><dd>${esc(date(e.createdAt))}</dd><dt>${esc(t('changes'))}</dt><dd>${e.lossReport?.length||0}</dd></dl>${e.lossReport?.length?`<ul class="report">${e.lossReport.map(r=>`<li>${esc(r.gene)} · ${esc(t(r.reason||r.kind))}</li>`).join('')}</ul>`:''}</details>`;}
function dropzone(portrait,target){return `<div class="portrait-drop" data-portrait-target="${target}" tabindex="0" role="button" aria-label="${esc(t('addPortrait'))}">${portrait?.dataUrl?`<img src="${esc(portrait.dataUrl)}" alt="${esc(t('currentPortrait'))}">`:`<span class="portrait-symbol">＋</span><strong>${esc(t('addPortrait'))}</strong><small>${esc(t('portraitHelp'))}</small>`}</div>`;}
function renderEditor(){geneEditSession=null;
 const w=state.work;if(!w){$('main').innerHTML=heading('edit','subtitle')+empty('emptyEditor','emptyEditorHelp',btn('new','newDna','primary')+btn('browse','browseLibrary'));return;}
 $('main').innerHTML=`<div class="page-heading workspace-heading"><div><div class="workspace-name"><h2>${esc(w.name)}</h2><span class="tag ${dirty()?'warn':''}">${esc(t(dirty()?'unsaved':'saved'))}</span></div><div class="workspace-meta"><span>${esc(profile(w.profile))}</span><span>·</span><span>${esc(format(w.format))}</span><span>·</span><span id="changedCount">${esc(t('edits',{count:changedGenes()}))}</span></div></div><div class="actions">${btn('undo','undo','small',!w.undo.length?'disabled':'')}${btn('redo','redo','small',!w.redo.length?'disabled':'')}${btn('save-work',w.savedId?'saveVariant':'saveLibrary','primary',w.encoding||w.encodeError||state.codeDraft?'disabled':'')}${btn('prepare-work','prepare','',!w.ready||w.encoding||w.encodeError||state.codeDraft?'disabled':'')}</div></div><nav class="subnav" aria-label="${esc(t('edit'))}">${['overview','genes','code'].map(v=>`<button data-action="edit-view" data-view="${v}" class="${state.view===v?'active':''}" aria-pressed="${state.view===v}">${esc(t(v))}</button>`).join('')}</nav><div id="editorStatus" class="status-line ${w.encodeError?'error':''}">${w.encoding?esc(t('encoding')):w.encodeError?esc(t('encodeError'))+' '+esc(t(w.encodeError)):''}</div><section id="editorContent">${state.view==='overview'?overview(w):state.view==='genes'?genesView(w):codeView(w)}</section>`;
}
function overview(w){return `<div class="edit-overview"><section>${dropzone(w.portrait,'work')}<div class="actions" style="margin-top:10px">${btn('paste-portrait','pasteImage','small',`data-target="work"`)}${w.portrait?btn('remove-portrait','removePortrait','small ghost',`data-target="work"`):''}</div><p class="portrait-caption">${esc(t('noPreview'))}</p></section><section><h3 class="section-title">${esc(t('characterDetails'))}</h3><div class="form-stack">${field('name',`<input id="workName" value="${esc(w.name)}" maxlength="120" required>`)}${field('sex',`<select id="workSex">${sexOptions(w.sex)}</select>`)}${field('note',`<textarea id="workNote" rows="4" maxlength="2000">${esc(w.note)}</textarea>`)}</div></section><section class="overview-summary"><h3 class="section-title">${esc(t('dnaSummary'))}</h3><div class="summary-stats">${[['geneCount',w.genes.length],['changedGenes',changedGenes()],['unknownGenes',w.genes.filter(g=>!g.known).length]].map(([k,v])=>`<div class="summary-stat"><span>${esc(t(k))}</span><strong>${v}</strong></div>`).join('')}</div><p class="hint">${esc(t('originalKept'))}</p>${!w.ready?`<p class="hint">${esc(t('geneUnavailable'))}</p>`:''}</section></div><section class="conversion-section"><h3 class="section-title">${esc(t('conversion'))}</h3><p class="hint">${esc(t('conversionHelp'))}</p><div class="conversion-controls">${field('targetProfile',`<select id="convertTarget">${profileOptions(state.target)}</select>`)}${field('outputFormat',`<select id="convertFormat">${['encoded','ruler_designer'].map(x=>option(x,format(x),state.targetFormat)).join('')}</select>`)}${check('convertLossy','allowLossy',state.lossy)}${btn('convert','convert','',!w.ready||w.encoding||w.encodeError?'disabled':'')}</div><div id="conversionResult">${conversionHtml()}</div></section>`;}
function conversionHtml(){const c=state.conversion;if(!c)return '';return `<div class="conversion-result"><h4>${esc(c.conversionSucceeded?t('conversionReady',{count:c.lossReport?.length||0}):t(c.conversionError||'failed'))}</h4><p class="hint">${esc(t('preserved'))}: ${c.preservedGeneCount??'–'}</p><ul class="report">${(c.validationMessages||[]).map(m=>`<li>${esc(t(m.message||m))}</li>`).join('')}${(c.lossReport||[]).map(r=>`<li><strong>${esc(r.gene)}</strong> · ${esc(t(r.reason||r.kind))}${r.source!=null?' · '+esc(typeof r.source==='string'?r.source:JSON.stringify(r.source)):''} → ${esc(typeof r.target==='string'?r.target:JSON.stringify(r.target))}</li>`).join('')}</ul>${c.conversionSucceeded?btn('save-converted','saveConverted','primary'):''}</div>`;}
function genesView(w){const cats=[...new Set(w.genes.map(g=>g.category||'other'))].sort();return `${!w.ready?`<p class="hint">${esc(t('geneUnavailable'))}</p>`:''}<div class="gene-toolbar"><input id="geneSearch" type="search" placeholder="${esc(t('searchGenes'))}" aria-label="${esc(t('searchGenes'))}" value="${esc(state.geneSearch)}"><select id="geneCategory" aria-label="${esc(t('allCategories'))}">${option('all',t('allCategories'),state.category)+cats.map(x=>option(x,categoryLabel(x),state.category)).join('')}</select>${check('geneChanged','changedOnly',state.changed)}${check('geneUnknown','unknownOnly',state.unknown)}${btn('reset-genes','resetGenes','small ghost',!changedGenes()?'disabled':'')}</div><p class="hint">${esc(t('paletteHelp'))}</p><div id="geneResults">${geneResults(w)}</div>`;}
function categoryLabel(value){const labels={face:['Face','Gesicht'],eyes:['Eyes','Augen'],nose:['Nose','Nase'],mouth:['Mouth','Mund'],hair:['Hair','Haare'],skin:['Skin','Haut'],body:['Body','Körper'],color:['Color palettes','Farbpaletten'],colors:['Color palettes','Farbpaletten'],other:['Other','Sonstige'],unknown:['Unknown','Unbekannt'],head:['Head','Kopf'],ears:['Ears','Ohren'],chin:['Chin','Kinn'],jaw:['Jaw','Kiefer'],neck:['Neck','Hals'],brows:['Brows','Augenbrauen'],special:['Special','Spezial']};const lower=String(value).toLowerCase();const extra={'jaw & cheeks':['Jaw & cheeks','Kiefer und Wangen'],dragon:['Dragon','Drache'],accessories:['Accessories','Accessoires']};return (labels[lower]||extra[lower])?.[window.I18n.language==='de'?1:0]||value;}
function geneResults(w){const rows=w.genes.filter(g=>(!state.geneSearch||`${g.name} ${g.label||''} ${g.values?.join(' ')||''}`.toLowerCase().includes(state.geneSearch.toLowerCase()))&&(state.category==='all'||g.category===state.category)&&(!state.changed||JSON.stringify(g.values)!==JSON.stringify(w.baseline[g.name]))&&(!state.unknown||!g.known||g.editable===false));const groups=new Map();for(const g of rows){const category=g.category||'Other';if(!groups.has(category))groups.set(category,[]);groups.get(category).push(g);}const order=['Colors','Face','Eyes','Nose','Mouth','Jaw & cheeks','Hair','Body','Accessories','Dragon','Other'];const rank=key=>order.indexOf(key)<0?order.length:order.indexOf(key);const sorted=[...groups].sort((a,b)=>rank(a[0])-rank(b[0]));return `<div class="gene-caption"><span>${rows.length} / ${w.genes.length} ${esc(t('genes'))}</span><div class="actions">${btn('expand-genes','expandAll','small ghost')}${btn('collapse-genes','collapseAll','small ghost')}</div></div><div class="gene-groups">${rows.length?sorted.map(([category,genes])=>`<details class="gene-group" data-gene-category="${esc(category)}" ${state.geneSearch||!closedGeneGroups.has(category)?'open':''}><summary><span>${esc(categoryLabel(category))}</span><span class="group-count">${genes.length}</span></summary><div class="gene-list">${genes.map(g=>geneRow(g,w)).join('')}</div></details>`).join(''):`<div class="empty-small">${esc(t('noGeneMatches'))}</div>`}</div>`;}
function geneRow(g,w){const changed=JSON.stringify(g.values)!==JSON.stringify(w.baseline[g.name]);const editable=w.ready&&g.editable!==false&&Array.isArray(g.values)&&g.values.length===4;return `<article class="gene-row" data-gene-row="${esc(g.name)}"><div class="gene-title"><strong>${esc(g.label||g.name.replace(/^gene_/,'').replace(/_/g,' '))}</strong><code>${esc(g.name)}</code>${changed?`<span class="tag">${esc(t('changedOnly').replace(' only','').replace('Nur ',''))}</span>`:''}${!editable?`<span class="tag muted">${esc(t('readOnly'))}</span>`:''}</div>${editable?`<div class="gene-alleles">${[0,1].map(allele=>{const i=allele*2;return `<div class="allele"><span class="allele-label">${esc(t(allele?'recessive':'dominant'))}${g.kind==='color'?` <button type="button" class="palette-swatch" data-action="choose-palette" data-gene="${esc(g.name)}" data-allele="${allele}" aria-label="${esc(t('choosePalette')+' '+g.name+' '+t(allele?'recessive':'dominant'))}" data-swatch-gene="${esc(g.name)}" data-swatch-index="${allele}" title="${esc(t('approximation'))}" style="background:${/^#[0-9a-f]{6}$/i.test(g.swatches?.[allele]||'')?g.swatches[allele]:'transparent'}"></button>`:''}</span>${g.kind==='color'?`<div class="coordinate-pair">${[i,i+1].map((j)=>`<label>${esc(t(j%2?'coordY':'coordX'))}<input type="number" data-gene="${esc(g.name)}" data-index="${j}" min="0" max="255" step="1" value="${esc(g.values[j])}" aria-label="${esc(g.name+' '+t(allele?'recessive':'dominant')+' '+t(j%2?'coordY':'coordX'))}"></label>`).join('')}</div>`:`<select data-gene="${esc(g.name)}" data-index="${i}" aria-label="${esc(g.name+' '+t(allele?'recessive':'dominant')+' '+t('template'))}">${[...new Set([g.values[i],...(g.options||[])])].map(token=>option(token,token,g.values[i])).join('')}</select><div class="strength-line"><input type="range" data-gene="${esc(g.name)}" data-index="${i+1}" min="0" max="255" step="1" value="${esc(g.values[i+1])}" aria-label="${esc(g.name+' '+t(allele?'recessive':'dominant')+' '+t('strength'))}"><input type="number" data-gene="${esc(g.name)}" data-index="${i+1}" min="0" max="255" step="1" value="${esc(g.values[i+1])}" aria-label="${esc(g.name+' '+t(allele?'recessive':'dominant')+' '+t('strength'))}"></div>`}</div>`;}).join('')}</div>`:`<div class="gene-raw">${esc(g.values?JSON.stringify(g.values):t('readOnly'))}</div>`}<button class="icon-button ghost" data-action="reset-gene" data-gene="${esc(g.name)}" title="${esc(t('resetGene'))}" aria-label="${esc(t('resetGene')+' '+g.name)}" ${!changed||!Object.hasOwn(w.baseline,g.name)?'disabled':''}>↺</button></article>`;}
function currentCodeText(w){if(state.codeFormat==='encoded')return w.encoded||'';if(state.codeFormat==='ruler_designer')return w.rulerDesigner||'';return w.output||'';}
function codeView(w){const original=state.codeSource==='original',text=original?w.original:(state.codeDraft??currentCodeText(w)),available=original||!!text;const error=state.codeFormat==='encoded'?w.encodingError:w.rulerDesignerError;return `<p class="hint">${esc(t('codeHelp'))}</p><div class="code-controls"><div class="segmented">${['current','original'].map(v=>`<button data-action="code-source" data-source="${v}" class="${state.codeSource===v?'active':''}">${esc(t(v))}</button>`).join('')}</div><select id="codeFormat" aria-label="${esc(t('representation'))}" ${original?'disabled':''}>${['encoded','ruler_designer'].map(v=>option(v,format(v),state.codeFormat)).join('')}</select><div class="actions">${btn('copy-code','copy','small',!available?'disabled':'')}${btn('export-code','exportText','small',!available?'disabled':'')}</div></div>${!available?`<div class="code-unavailable"><h3>${esc(t('representationUnavailable'))}</h3><p>${esc(t(error||'cannotRepresent'))}</p></div>`:`<textarea id="codeEditor" class="code-editor" spellcheck="false" ${original?'readonly':''} aria-label="${esc(t(original?'original':'current'))}">${esc(text)}</textarea>`}<div class="code-footer"><span class="status-line ${state.codeDraft!==null?'error':''}" id="codeStatus">${esc(t(original?'immutable':state.codeDraft!==null?'codeDirty':'working'))}</span><div class="actions">${!original&&available?btn('discard-code','discardCode','small ghost',state.codeDraft===null?'disabled':'')+btn('apply-code','applyCode','small primary',state.codeDraft===null?'disabled':''):''}</div></div>${!original&&state.codeFormat==='ruler_designer'&&w.rulerDesignerMetadataSynthetic?`<p class="hint">${esc(t('syntheticMetadata'))}</p>`:''}`;}
function gameCharacterMarkup(){const g=state.game,ready=!!g?.ready;return `<span class="connection-state ${ready?'ready':''}">${esc(t(ready?'connected':'disconnected'))}</span><div class="game-character"><span class="eyebrow">${esc(t('selectedCharacter'))}</span><h3>${esc(ready?g.name:t('noCharacter'))}</h3><div class="facts"><span>ID <strong>${ready?esc(g.id):'–'}</strong></span><span>${esc(t('genes'))} <strong>${ready?esc(g.geneCount):'–'}</strong></span><span>CK3 ${esc(g?.gameVersion||'–')}</span></div>${!ready&&g?.message?`<p class="hint">${esc(t(g.message))}</p>`:''}</div><div class="actions">${btn('read-game','readCharacter','',!ready||state.gameBusy?'disabled':'')}${btn('copy-game','copyGame','ghost',!ready||state.gameBusy?'disabled':'')}</div>`;}
function renderConnection(){$('main').innerHTML=heading('connection','connectionIntro',btn('refresh-game','refresh','ghost'))+`<p class="hint">${esc(t('connectionHelp'))}</p><div class="connection-grid"><section class="connection-section" id="gameCharacterPanel">${gameCharacterMarkup()}</section><section class="connection-section"><h3 class="section-title">${esc(t('preparedDna'))}</h3><p class="hint">${esc(t('prepareHelp'))}</p>${field('library',`<select id="preparedSelect">${option('',t('chooseSaved'),state.prepared)+state.library.map(e=>option(e.id,`${e.name} · ${profile(e.profile)}${e.format==='original'?' · '+t('unverified'):''}`,state.prepared)).join('')}</select>`)}<p id="compatibilityText" class="status-line"></p>${btn('apply-prepared','applyPrepared','primary','disabled')}<details id="gameCompatibilityDetails" hidden><summary>${esc(t('details'))}</summary><pre id="gameCompatibilityReport" class="report"></pre></details></section></div><section class="clipboard-section"><h3 class="section-title">${esc(t('clipboardTransfer'))}</h3><p class="hint">${esc(t('clipboardHelp'))}</p>${btn('apply-clipboard','applyClipboard','',!state.game?.ready||state.gameBusy?'disabled':'')}</section><p id="gameMessage" class="status-line" style="margin-top:24px">${esc(t(state.gameMessage))}</p>`;syncCompatibility();}
function syncCompatibility(){if(state.page!=='connection')return;const text=$('compatibilityText');if(text){text.textContent=t(state.compatibility?.reason||(state.compatibility?(state.compatibility.compatible?'compatible':'incompatible'):'noPrepared'));text.className='status-line'+(state.compatibility?.compatible?' success':'');}const apply=document.querySelector('[data-action="apply-prepared"]');if(apply)apply.disabled=!canApply();const details=$('gameCompatibilityDetails');if(details)details.hidden=!state.compatibility;const report=$('gameCompatibilityReport');if(report)report.textContent=JSON.stringify(state.compatibility?.details||state.compatibility?.checks||{},null,2);}
function syncConnectionStatus(){if(state.page!=='connection')return;const panel=$('gameCharacterPanel');if(panel)panel.innerHTML=gameCharacterMarkup();const paste=document.querySelector('[data-action="apply-clipboard"]');if(paste)paste.disabled=!state.game?.ready||state.gameBusy;syncCompatibility();if($('gameMessage'))$('gameMessage').textContent=t(state.gameMessage);}
function renderSettings(){$('main').innerHTML=heading('settings','settingsIntro')+`<div class="settings-body"><h3 class="section-title">${esc(t('installation'))}</h3><p class="hint">${esc(t('pathHelp'))}</p>${['game','epe','agot'].map(kind=>`<div class="settings-path"><strong>${esc(kind==='game'?t('baseGame'):kind.toUpperCase())}</strong><span class="path">${esc(state.paths[kind]||t('automatic'))}</span>${btn('choose-path','chooseFolder','',`data-kind="${kind}" ${state.pathsBusy?'disabled':''}`)}</div>`).join('')}<div class="actions" style="margin-top:20px">${btn('reset-paths','resetPaths','ghost',state.pathsBusy?'disabled':'')}</div><p class="status-line">${state.pathsBusy?esc(t('updating')):''}</p><h3 class="section-title">${esc(t('definitions'))}</h3><div class="definition-list">${['none','epe','agot'].map(p=>{const s=state.schemas[p];return `<div class="definition-row"><strong>${esc(profile(p))}</strong><span>${s&&s.available!==false&&!s.error?`${s.geneCount??'–'} ${esc(t('genes'))}${s.version?' · '+esc(s.version):''}`:esc(t(s?.error||'unavailable'))}</span></div>`;}).join('')}</div><p class="hint" style="margin-top:25px">${esc(t('version',{version:state.version||'–'}))}</p><section class="about-section"><h3 class="section-title">${esc(t('about'))}</h3><h4>Crusader Kings III DNA Studio</h4><p class="hint">${esc(t('aboutDescription'))}</p><dl class="metadata"><dt>${esc(t('versionLabel'))}</dt><dd>${esc(state.version||'–')}</dd><dt>${esc(t('technology'))}</dt><dd>Electron · Python · Pillow</dd><dt>${esc(t('icons'))}</dt><dd>Lucide · ISC</dd></dl><p class="hint">${esc(t('aboutUnofficial'))}</p><p class="hint">${esc(t('aboutOffline'))}</p></section></div>`;}
function renderNew(){
 const d=newDraft;if(!d)return;const dialog=$('newDialog');const open=dialog.open;
 dialog.innerHTML=`<div class="dialog-top"><h2 id="newTitle">${esc(t('newDna'))}</h2>${btn('close-new','cancel','ghost small')}</div><p class="hint">${esc(t('newIntro'))}</p><div class="dialog-grid"><section>${field('dna',`<textarea id="newDnaText" class="dialog-dna" spellcheck="false" placeholder="${esc(t('pasteDna'))}">${esc(d.text)}</textarea>`)}<div class="actions" style="margin-top:10px">${btn('new-file','loadFile','small')}${btn('new-paste','pasteClipboard','small')}</div><div id="newDetection">${detectionHtml()}</div>${field('sourceProfile',`<select id="newProfile">${option('auto',t('autoDetect'),d.profile)+profileOptions(d.profile)}</select>`)}<div class="dialog-meta" style="margin-top:20px">${field('name',`<input id="newName" value="${esc(d.name)}" maxlength="120" autocomplete="off" required>`,'full')}${field('sex',`<select id="newSex">${sexOptions(d.sex)}</select>`,'full')}${field('note',`<textarea id="newNote" rows="3" maxlength="2000">${esc(d.note)}</textarea>`,'full')}</div></section><section>${dropzone(d.portrait,'new')}<p class="portrait-caption">${esc(t('portraitHelp'))}</p><div class="actions">${btn('paste-portrait','pasteImage','small',`data-target="new"`)}${d.portrait?btn('remove-portrait','removePortrait','small ghost',`data-target="new"`):''}</div><p class="hint">${esc(t('archiveHelp'))}</p></section></div><p id="newError" class="status-line error">${esc(d.error?t(d.error):'')}</p><div class="dialog-actions">${btn('close-new','cancel','ghost')}${btn('archive-new','archiveOriginal','ghost',`${d.result?.status==='ready'?'hidden':''} ${!d.text.trim()||d.checking?'disabled':''}`)}${btn('open-new','openEditor','',d.result?.status!=='ready'||d.checking?'disabled':'')}${btn('create-new','createEntry','primary',d.result?.status!=='ready'||d.checking?'disabled':'')}</div>`;
 if(!open)dialog.showModal();
}
function detectionHtml(){const d=newDraft;if(!d)return '';const r=d.result;let key=d.checking?'detecting':!d.text?'awaitingDna':r?.status==='ready'?'detected':d.error?'unsupported':r?.status==='ambiguous'?'ambiguous':'unsupported';return `<div class="detection ${r?.status==='unsupported'||d.error?'error':''}" role="status"><strong>${esc(t(key,{count:r?.geneCount||0}))}</strong>${r?`<div class="detected-meta">${esc(format(r.format))} · ${esc(r.profile?profile(r.profile):(r.candidates||[]).map(profile).join(' / ')||t('unknown'))}</div>${(r.messages||[]).map(m=>`<div class="detected-meta">${esc(t(m))}</div>`).join('')}`:''}</div>`;}
function refreshDetection(){if(!newDraft||!$('newDialog').open)return;$('newDetection').innerHTML=detectionHtml();$('newError').textContent=newDraft.error?t(newDraft.error):'';document.querySelector('[data-action="open-new"]').disabled=newDraft.checking||newDraft.result?.status!=='ready';document.querySelector('[data-action="archive-new"]').disabled=newDraft.checking||!newDraft.text.trim();document.querySelector('[data-action="archive-new"]').hidden=newDraft.result?.status==='ready';document.querySelector('[data-action="create-new"]').disabled=newDraft.checking||newDraft.result?.status!=='ready';}
function showNew(text='',metadata={}){newDraft={text,profile:'auto',name:metadata.name||'',sex:metadata.sex||'unspecified',note:metadata.note||'',portrait:metadata.portrait||null,result:null,checking:false,error:''};renderNew();$('newDnaText').focus();if(text)scheduleDetect(0);}
function scheduleDetect(delay=280){clearTimeout(detectTimer);const rev=++detectRevision;if(!newDraft)return;newDraft.result=null;newDraft.error='';if(!newDraft.text.trim()){newDraft.checking=false;refreshDetection();return;}newDraft.checking=true;refreshDetection();detectTimer=setTimeout(async()=>{const d=newDraft;if(!d)return;try{const result=await api.studioDetect({text:d.text,profile:d.profile});if(rev!==detectRevision||newDraft!==d)return;d.result=result;}catch(e){if(rev!==detectRevision||newDraft!==d)return;d.error=e.message;}finally{if(rev===detectRevision&&newDraft===d){d.checking=false;refreshDetection();}}},delay);}
async function confirmAction(title,help,actionKey,values={}){const dialog=$('confirmDialog');dialog.innerHTML=`<h2 id="confirmTitle">${esc(t(title,values))}</h2><p class="confirm-copy">${esc(t(help,values))}</p><div class="dialog-actions">${btn('confirm-no','cancel','ghost')}${btn('confirm-yes',actionKey,'primary')}</div>`;dialog.showModal();return new Promise(resolve=>{confirmResolve=resolve;});}
async function mayReplace(){return !dirty()||await confirmAction('replaceTitle','replaceHelp','replace');}
async function openNew(){const d=newDraft;if(!d||d.checking||d.result?.status!=='ready')return;if(!d.name.trim()){d.error='requiredName';refreshDetection();$('newName').focus();return;}if(!await mayReplace())return;await openWorking(d.result,{...d,original:d.text,sourceProfile:d.result.profile});$('newDialog').close();newDraft=null;}
function normalizedDna(r,text){return r.output||r.convertedOutput||(r.format==='encoded'?(r.encoded||text.trim()):(r.normalized||text));}
async function openWorking(result,meta={}){
 const genes=clone(result.genes||[]);const original=meta.original??result.original??meta.text??'';const source=meta.text??original;
 state.work={name:meta.name||t('untitled'),sex:meta.sex||'unspecified',note:meta.note||'',favorite:!!meta.favorite,portrait:meta.portrait||null,portraitChanged:false,original,source,originalProfile:['none','epe','agot'].includes(meta.sourceProfile)?meta.sourceProfile:(result.profile||'unknown'),profile:result.profile||'unknown',importMetadata:clone(meta.importMetadata||null),format:result.format||'original',schemaInfo:clone(result.schemaInfo||null),genes,baseline:Object.fromEntries(genes.map(g=>[g.name,clone(g.values)])),output:normalizedDna(result,source),encoded:result.encoded||null,encodingError:result.encodingError||'',rulerDesigner:result.rulerDesigner||(result.format==='ruler_designer'?source:null),rulerDesignerError:result.rulerDesignerError||'',rulerDesignerMetadataSynthetic:!!result.rulerDesignerMetadataSynthetic,ready:result.status==='ready',savedId:meta.savedId||null,dirty:!meta.savedId||(meta.format==='original'&&result.status==='ready'),undo:[],redo:[],encoding:false,encodeError:'',lossReport:clone(meta.lossReport||[])};
 encodeRevision++;clearTimeout(encodeTimer);state.codeDraft=null;state.codeSource='current';state.codeFormat=['encoded','ruler_designer'].includes(state.work.format)?state.work.format:'ruler_designer';state.view='overview';state.conversion=null;state.geneSearch='';state.category='all';state.changed=false;state.unknown=false;state.target=state.work.profile==='unknown'?'none':state.work.profile;navigate('edit');
}
async function loadEntry(id,original=false){const entry=state.library.find(e=>e.id===id);if(!entry||!await mayReplace())return;const text=original?(entry.originalDna||entry.dna):entry.dna,sourceProfile=original?entry.sourceProfile:entry.profile;let r;try{r=await api.studioDetect({text,profile:['none','epe','agot'].includes(sourceProfile)?sourceProfile:'auto'});}catch(error){if(entry.format!=='original')throw error;r={status:'unsupported',format:'original',profile:null,genes:[],original:text,messages:[error.message]};}const p=entry.thumbnail?await api.libraryPortrait(id):null;if(p)portraits.set(id,p);await openWorking(r,{...entry,text,original:entry.originalDna||entry.dna,sourceProfile:entry.sourceProfile,savedId:original?null:id,portrait:p,lossReport:original?[]:entry.lossReport});}
function workSnapshot(w){return {genes:clone(w.genes),source:w.source,output:w.output,encoded:w.encoded,encodingError:w.encodingError,rulerDesigner:w.rulerDesigner,rulerDesignerError:w.rulerDesignerError,rulerDesignerMetadataSynthetic:w.rulerDesignerMetadataSynthetic,format:w.format,profile:w.profile,schemaInfo:clone(w.schemaInfo),ready:w.ready,lossReport:clone(w.lossReport),dirty:w.dirty};}
function pushUndo(){const w=state.work;w.undo.push(workSnapshot(w));if(w.undo.length>100)w.undo.shift();w.redo=[];}
function restoreSnapshot(snapshot){const w=state.work;for(const k of Object.keys(snapshot))w[k]=clone(snapshot[k]);w.encodeError='';state.codeDraft=null;state.conversion=null;}
function undo(redo=false){geneEditSession=null;const w=state.work;if(!w)return;const from=redo?w.redo:w.undo,to=redo?w.undo:w.redo;if(!from.length)return;clearTimeout(encodeTimer);encodeRevision++;to.push(workSnapshot(w));restoreSnapshot(from.pop());w.encoding=false;scheduleEncode(0);renderEditor();}
function updateGene(node){const w=state.work,g=w?.genes.find(g=>g.name===node.dataset.gene);if(!g||g.editable===false||!w.ready)return;const index=Number(node.dataset.index);let value=node.tagName==='SELECT'?node.value:Number(node.value);if(node.tagName!=='SELECT'&&(!Number.isInteger(value)||value<0||value>255)){node.setAttribute('aria-invalid','true');return;}node.removeAttribute('aria-invalid');if(g.values[index]===value)return;
 // One focused number edit or one slider gesture forms one undo step.
 if(node.tagName==='SELECT'){pushUndo();geneEditSession=null;}else if(!geneEditSession||geneEditSession.node!==node||geneEditSession.work!==w){pushUndo();geneEditSession={node,work:w};}
 g.values[index]=value;w.dirty=true;w.lossReport=[];state.conversion=null;state.codeDraft=null;
 for(const peer of document.querySelectorAll('[data-gene][data-index]'))if(peer.dataset.gene===g.name&&peer.dataset.index===String(index)&&peer!==node)peer.value=String(value);
 const row=node.closest('.gene-row');const reset=row?.querySelector('[data-action="reset-gene"]');if(reset)reset.disabled=JSON.stringify(g.values)===JSON.stringify(w.baseline[g.name]);
 $('changedCount').textContent=t('edits',{count:changedGenes()});refreshWorkingSwatches(w);scheduleEncode();updateEditorActions();
}
function updateEditorActions(){const w=state.work;if(!w||state.page!=='edit')return;const save=document.querySelector('[data-action="save-work"]');if(save)save.disabled=w.encoding||!!w.encodeError||state.codeDraft!==null;const prepare=document.querySelector('[data-action="prepare-work"]');if(prepare)prepare.disabled=!w.ready||w.encoding||!!w.encodeError||state.codeDraft!==null;const undoBtn=document.querySelector('[data-action="undo"]');if(undoBtn)undoBtn.disabled=!w.undo.length;const redoBtn=document.querySelector('[data-action="redo"]');if(redoBtn)redoBtn.disabled=!w.redo.length;const status=$('editorStatus');if(status){status.textContent=w.encoding?t('encoding'):w.encodeError?t('encodeError')+' '+t(w.encodeError):'';status.className='status-line'+(w.encodeError?' error':'');}const badge=document.querySelector('.workspace-name .tag');if(badge){badge.textContent=t(dirty()?'unsaved':'saved');badge.className='tag'+(dirty()?' warn':'');}}
function updateRepresentations(w,result){w.encoded=result.encoded||null;w.encodingError=result.encodingError||'';w.rulerDesigner=result.rulerDesigner||(result.format==='ruler_designer'?result.output||result.normalized:null);w.rulerDesignerError=result.rulerDesignerError||'';w.rulerDesignerMetadataSynthetic=!!result.rulerDesignerMetadataSynthetic;}
function refreshWorkingSwatches(w,result){if(result){const byName=new Map((result.genes||[]).map(g=>[g.name,g]));for(const gene of w.genes){const received=byName.get(gene.name);if(received&&Object.hasOwn(received,'swatches'))gene.swatches=clone(received.swatches);}}for(const g of w.genes){const cached=paletteCache.get(w.profile+':'+g.name);if(cached?.canvas&&g.kind==='color')g.swatches=[samplePalette(cached.canvas,g.values[0],g.values[1]),samplePalette(cached.canvas,g.values[2],g.values[3])];}for(const node of document.querySelectorAll('[data-swatch-gene]')){const value=w.genes.find(g=>g.name===node.dataset.swatchGene)?.swatches?.[Number(node.dataset.swatchIndex)];node.style.background=/^#[0-9a-f]{6}$/i.test(value||'')?value:'transparent';}}
function scheduleEncode(delay=220){clearTimeout(encodeTimer);const revision=++encodeRevision,w=state.work;if(!w?.ready)return;w.encoding=true;w.encodeError='';updateEditorActions();encodeTimer=setTimeout(async()=>{const genes=w.genes.map(g=>({name:g.name,values:clone(g.values)}));try{const result=await api.studioEncode({text:w.source,profile:w.profile,genes,targetFormat:w.format});if(revision!==encodeRevision||state.work!==w)return;w.output=result.output||result.convertedOutput;w.schemaInfo=clone(result.schemaInfo||w.schemaInfo);updateRepresentations(w,result);refreshWorkingSwatches(w,result);w.encoding=false;w.encodeError='';if(state.page==='edit'&&state.view==='code'&&state.codeDraft===null&&state.codeSource==='current')$('editorContent').innerHTML=codeView(w);}catch(e){if(revision!==encodeRevision||state.work!==w)return;w.encoding=false;w.encodeError=e.message||'failed';}finally{if(revision===encodeRevision&&state.work===w)updateEditorActions();}},delay);}
function payloadFromWork(w){const archive=!w.ready||w.format==='original';return {name:w.name.trim(),note:w.note,sex:w.sex,favorite:!!w.favorite,dna:archive?w.original:w.output,originalDna:w.original,format:archive?'original':w.format,profile:archive?'unknown':w.profile,sourceProfile:archive?'unknown':w.originalProfile,verification:archive?'unverified':'validated',schemaInfo:archive?null:clone(w.schemaInfo),lossReport:archive?[]:clone(w.lossReport||[]),...(w.importMetadata?{importMetadata:clone(w.importMetadata)}:{}),thumbnail:null};}
function saveSignature(w){return JSON.stringify({payload:payloadFromWork(w),genes:w.genes.map(g=>({name:g.name,values:g.values})),portrait:w.portrait?.dataUrl||null,codeDraft:state.codeDraft});}
async function saveWorking(){const w=state.work;if(!w||w.encoding||w.encodeError||state.codeDraft!==null)throw new Error(t('encodeError'));if(!w.name.trim())throw new Error(t('requiredName'));const payload=clone(payloadFromWork(w)),portrait=clone(w.portrait),signature=saveSignature(w);const entry=await api.librarySave(payload);if(portrait?.bytes)await api.libraryPortraitSet(entry.id,portrait.bytes);else if(portrait?.dataUrl)await api.libraryPortraitSet(entry.id,dataUrlBytes(portrait.dataUrl));if(state.work===w&&saveSignature(w)===signature){w.savedId=entry.id;w.dirty=false;}state.selected=entry.id;await refreshLibrary();toast('stored');if(state.page==='edit')renderEditor();return entry;}

function dataUrlBytes(url){const data=atob(url.split(',')[1]);return Uint8Array.from(data,c=>c.charCodeAt(0));}

async function createNew(){const d=newDraft,r=d?.result;if(!d||d.checking||r?.status!=='ready')return;if(!d.name.trim()){d.error='requiredName';refreshDetection();$('newName').focus();return;}const entry=await api.librarySave({name:d.name.trim(),note:d.note,sex:d.sex,favorite:false,dna:normalizedDna(r,d.text),originalDna:d.text,format:r.format,profile:r.profile,sourceProfile:r.profile,verification:'validated',schemaInfo:clone(r.schemaInfo||null),lossReport:[],thumbnail:null});if(d.portrait?.bytes)await api.libraryPortraitSet(entry.id,d.portrait.bytes);else if(d.portrait?.dataUrl)await api.libraryPortraitSet(entry.id,dataUrlBytes(d.portrait.dataUrl));$('newDialog').close();newDraft=null;state.selected=entry.id;await refreshLibrary();navigate('library');toast('stored');}
async function archiveNew(){const d=newDraft;if(!d||!d.text.trim()||d.checking)return;if(!d.name.trim()){d.error='requiredName';refreshDetection();$('newName').focus();return;}const entry=await api.librarySave({name:d.name.trim(),note:d.note,sex:d.sex,favorite:false,dna:d.text,originalDna:d.text,format:'original',profile:'unknown',sourceProfile:'unknown',verification:'unverified',schemaInfo:null,lossReport:[],thumbnail:null});if(d.portrait?.bytes)await api.libraryPortraitSet(entry.id,d.portrait.bytes);$('newDialog').close();newDraft=null;state.selected=entry.id;await refreshLibrary();navigate('library');toast('stored');}
async function refreshLibrary(){state.library=await api.libraryList();renderChrome();if(state.page==='library')renderLibrary();}
async function duplicateEntry(id){const e=state.library.find(e=>e.id===id);if(!e)return;const payload=Object.fromEntries(['name','note','sex','favorite','dna','originalDna','format','profile','sourceProfile','schemaInfo','lossReport','verification','importMetadata'].filter(k=>e[k]!==undefined).map(k=>[k,clone(e[k])]));payload.name=`${e.name.slice(0,108)} · ${t('copySuffix')}`;payload.thumbnail=null;const entry=await api.librarySave(payload);const portrait=e.thumbnail?await api.libraryPortrait(e.id):null;if(portrait)await api.libraryPortraitSet(entry.id,dataUrlBytes(portrait.dataUrl));state.selected=entry.id;await refreshLibrary();toast('duplicated');}
async function editMetadata(id){const e=state.library.find(e=>e.id===id);if(!e)return;const dialog=$('confirmDialog');dialog.innerHTML=`<h2 id="confirmTitle">${esc(t('editMetadata'))}</h2><div class="form-stack editing-details">${field('name',`<input id="entryName" maxlength="120" value="${esc(e.name)}">`)}${field('sex',`<select id="entrySex">${sexOptions(e.sex)}</select>`)}${field('note',`<textarea id="entryNote" maxlength="2000" rows="4">${esc(e.note)}</textarea>`)}</div><div class="dialog-actions">${btn('confirm-no','cancel','ghost')}${btn('save-metadata','save','primary',`data-id="${id}"`)}</div>`;dialog.showModal();}
async function convertWorking(){const w=state.work;if(!w?.ready||w.encoding||w.encodeError)return;state.conversion=null;const target=state.target,targetFormat=state.targetFormat,sourceText=w.output;const c=await api.analyzeAndConvert({text:sourceText,sourceMode:w.profile,targetMode:target,targetFormat,allowLossyEncodedFallbacks:state.lossy});if(state.work!==w||w.output!==sourceText||target!==state.target||targetFormat!==state.targetFormat)return;state.conversion={...c,sourceText,target,targetFormat,original:w.original,sourceProfile:w.originalProfile};if($('conversionResult'))$('conversionResult').innerHTML=conversionHtml();}
async function saveConverted(){const c=state.conversion,w=state.work;if(!c?.conversionSucceeded||!w)return;const portrait=clone(w.portrait);const entry=await api.librarySave({name:`${w.name.slice(0,100)} · ${profile(c.target)}`,note:w.note,sex:w.sex,favorite:false,dna:c.convertedOutput,format:c.targetFormat,profile:c.target,sourceProfile:c.sourceProfile,originalDna:c.original,schemaInfo:clone(c.schemaInfo),lossReport:clone(c.lossReport||[]),thumbnail:null,verification:'validated'});if(portrait?.dataUrl)await api.libraryPortraitSet(entry.id,dataUrlBytes(portrait.dataUrl));state.selected=entry.id;await refreshLibrary();toast('stored');}
async function applyCode(){const w=state.work;if(!w||state.codeDraft===null)return;const text=state.codeDraft;const result=await api.studioDetect({text,profile:w.profile==='unknown'?'auto':w.profile});if(result.status!=='ready')throw new Error(t(result.status==='ambiguous'?'ambiguous':'geneUnavailable'));pushUndo();w.genes=clone(result.genes||[]);w.source=text;w.output=normalizedDna(result,text);w.profile=result.profile;w.format=result.format;w.schemaInfo=clone(result.schemaInfo);updateRepresentations(w,result);state.codeFormat=result.format;w.ready=true;w.dirty=true;w.lossReport=[];w.encodeError='';state.codeDraft=null;state.conversion=null;encodeRevision++;clearTimeout(encodeTimer);w.encoding=false;renderEditor();}

function samplePalette(canvas,x,y){const color=canvas.getContext('2d',{willReadFrequently:true}).getImageData(Math.max(0,Math.min(255,Number(x))),Math.max(0,Math.min(255,Number(y))),1,1).data;return '#'+[...color].slice(0,3).map(v=>v.toString(16).padStart(2,'0')).join('');}
async function openPalette(geneName,allele=0){const w=state.work,g=w?.genes.find(g=>g.name===geneName);if(!w?.ready||g?.kind!=='color'||g.editable===false)return;let cached=paletteCache.get(w.profile+':'+geneName);if(!cached){if(!api.studioPalette)throw new Error(t('unavailableApi'));const data=await api.studioPalette({profile:w.profile,gene:geneName});if(!data?.dataUrl?.startsWith('data:image/png;base64,'))throw new Error(t('paletteUnavailable'));const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error(t('paletteUnavailable')));image.src=data.dataUrl;});const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;canvas.getContext('2d').drawImage(image,0,0,256,256);cached={...data,canvas};paletteCache.set(w.profile+':'+geneName,cached);}if(state.work!==w)return;paletteState={work:w,gene:geneName,values:clone(g.values),allele,both:false,palette:cached};let dialog=$('paletteDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='paletteDialog';dialog.setAttribute('aria-labelledby','paletteTitle');document.body.appendChild(dialog);dialog.addEventListener('cancel',()=>{paletteState=null;});}renderPalette();dialog.showModal();}
function renderPalette(){const p=paletteState;if(!p)return;$('paletteDialog').innerHTML=`<div class="dialog-top"><h2 id="paletteTitle">${esc(t('choosePalette'))}</h2>${btn('close-palette','cancel','small ghost')}</div><p class="hint">${esc(profile(p.work.profile))} · <code>${esc(p.gene)}</code> · ${esc(t('paletteApproximate'))}</p><div class="palette-layout"><section><canvas id="paletteCanvas" width="256" height="256" tabindex="0" role="application" aria-label="${esc(t('paletteKeyboard'))}"></canvas><p class="hint">${esc(t('paletteKeyboard'))}</p></section><section class="palette-controls">${[0,1].map(allele=>`<div class="palette-allele ${p.allele===allele?'active':''}"><button class="palette-allele-button" data-action="palette-allele" data-allele="${allele}">${esc(t(allele?'recessive':'dominant'))}<span class="palette-selection-swatch" data-palette-preview="${allele}"></span></button><div class="coordinate-pair">${[0,1].map(axis=>`<label>${esc(t(axis?'coordY':'coordX'))}<input type="number" data-palette-coord="${allele*2+axis}" min="0" max="255" step="1" value="${p.values[allele*2+axis]}" aria-label="${esc(t(allele?'recessive':'dominant')+' '+t(axis?'coordY':'coordX'))}"></label>`).join('')}</div></div>`).join('')}${check('paletteBoth','paletteBoth',p.both)}<p class="hint">${esc(t('paletteAxes'))}</p></section></div><div class="dialog-actions">${btn('close-palette','cancel','ghost')}${btn('apply-palette','applyPalette','primary')}</div>`;const canvas=$('paletteCanvas');canvas.addEventListener('pointerdown',event=>{if(state.busy)return;canvas.setPointerCapture(event.pointerId);choosePalettePosition(event);});canvas.addEventListener('pointermove',event=>{if(!state.busy&&event.buttons===1)choosePalettePosition(event);});canvas.addEventListener('keydown',event=>{const movement={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[event.key];if(!movement)return;event.preventDefault();const i=paletteState.allele*2;setPalettePair(paletteState.values[i]+movement[0],paletteState.values[i+1]+movement[1]);});paintPalette();}
function setPalettePair(x,y){const p=paletteState;if(!p)return;const pairs=p.both?[0,2]:[p.allele*2];for(const i of pairs){p.values[i]=Math.max(0,Math.min(255,Math.round(x)));p.values[i+1]=Math.max(0,Math.min(255,Math.round(y)));}paintPalette();}
function choosePalettePosition(event){const bounds=$('paletteCanvas').getBoundingClientRect();setPalettePair(Math.floor((event.clientX-bounds.left)*256/bounds.width),Math.floor((event.clientY-bounds.top)*256/bounds.height));}
function updatePaletteCoordinate(node){const p=paletteState,index=Number(node.dataset.paletteCoord),value=Number(node.value);if(!p||!Number.isInteger(value)||value<0||value>255){node.setAttribute('aria-invalid','true');return;}node.removeAttribute('aria-invalid');p.allele=Math.floor(index/2);p.values[index]=value;if(p.both)p.values[(index+2)%4]=value;paintPalette();}
function paintPalette(){const p=paletteState,canvas=$('paletteCanvas');if(!p||!canvas)return;const context=canvas.getContext('2d');context.clearRect(0,0,256,256);context.drawImage(p.palette.canvas,0,0);for(const allele of [0,1]){const i=allele*2;context.beginPath();context.arc(p.values[i]+.5,p.values[i+1]+.5,p.allele===allele?5:3,0,Math.PI*2);context.strokeStyle='#000';context.lineWidth=3;context.stroke();context.strokeStyle=allele?'#d9e7a9':'#fff';context.lineWidth=1.5;context.stroke();const swatch=document.querySelector(`[data-palette-preview="${allele}"]`);if(swatch)swatch.style.background=samplePalette(p.palette.canvas,p.values[i],p.values[i+1]);}for(const input of document.querySelectorAll('[data-palette-coord]'))if(input!==document.activeElement)input.value=p.values[Number(input.dataset.paletteCoord)];for(const node of document.querySelectorAll('.palette-allele'))node.classList.toggle('active',Number(node.querySelector('[data-allele]').dataset.allele)===p.allele);}
function applyPalette(){const p=paletteState;if(!p||state.work!==p.work)return;const w=p.work,g=w.genes.find(g=>g.name===p.gene);geneEditSession=null;if(JSON.stringify(g.values)!==JSON.stringify(p.values)){pushUndo();g.values=clone(p.values);w.dirty=true;w.lossReport=[];state.conversion=null;state.codeDraft=null;refreshWorkingSwatches(w);scheduleEncode(0);}$('paletteDialog').close();paletteState=null;renderEditor();}

async function stagePortrait(file,target){if(!file)return;if(file.size>12*1024*1024)throw new Error(t('imageTooLarge'));if(!file.type.startsWith('image/'))throw new Error(t('invalidImage'));const bytes=new Uint8Array(await file.arrayBuffer());const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error(t('invalidImage')));reader.readAsDataURL(file);});await setPortrait({bytes,dataUrl},target);}
async function setPortrait(p,target){if(!p)return;if(target==='new'&&newDraft){newDraft.portrait=p;renderNew();}else if(target==='work'&&state.work){state.work.portrait=p;state.work.dirty=true;state.work.portraitChanged=true;renderEditor();}else if(target.startsWith('entry:')){const id=target.slice(6);await api.libraryPortraitSet(id,p.bytes||dataUrlBytes(p.dataUrl));portraits.delete(id);await refreshLibrary();}}
async function choosePortrait(target){if(api.portraitChoose){const p=await api.portraitChoose();if(p)await setPortrait(p,target);}else{portraitTarget=target;$('portraitFile').click();}}
async function pastePortrait(target){if(api.portraitPaste){const p=await api.portraitPaste();if(p)await setPortrait(p,target);}else{const items=await navigator.clipboard.read();for(const item of items){const type=item.types.find(t=>t.startsWith('image/'));if(type){const blob=await item.getType(type);await stagePortrait(new File([blob],'portrait',{type}),target);break;}}}}
function targetKey(g=state.game){return g?.ready?`${g.pid}:${g.id}:${g.selectionToken}`:'';}
function expectedTarget(){return {pid:state.game.pid,id:state.game.id,selectionToken:state.game.selectionToken};}
function canApply(){return !!state.game?.ready&&!state.gameBusy&&!!state.compatibility?.compatible&&state.compatKey===`${state.prepared}:${targetKey()}`;}
function gameStatusSignature(game){return JSON.stringify([!!game?.ready,game?.pid,game?.id,game?.selectionToken,game?.name,game?.geneCount,game?.gameVersion,game?.message]);}
async function pollGame(){clearTimeout(pollTimer);if(state.page!=='connection'||pollInFlight||state.gameBusy)return;pollInFlight=true;try{const previousTarget=targetKey(),previousStatus=gameStatusSignature(state.game),next=await api.gameStatus();state.game=next;if(previousTarget!==targetKey()){compatRevision++;state.compatibility=null;state.compatKey='';state.gameMessage='';if(state.prepared)checkCompatibility();}if(previousStatus!==gameStatusSignature(next))syncConnectionStatus();}catch(e){const next={ready:false,message:e.message},changed=gameStatusSignature(state.game)!==gameStatusSignature(next);state.game=next;state.compatibility=null;state.compatKey='';if(changed)syncConnectionStatus();}finally{pollInFlight=false;if(state.page==='connection')pollTimer=setTimeout(pollGame,1400);}}
async function checkCompatibility(){const revision=++compatRevision,id=state.prepared;state.compatibility=null;state.compatKey='';syncCompatibility();if(!id||!state.game?.ready)return;const key=`${id}:${targetKey()}`;if($('compatibilityText'))$('compatibilityText').textContent=t('checking');try{const result=await api.libraryCheck({id,expectedTarget:expectedTarget()});if(revision!==compatRevision||key!==`${state.prepared}:${targetKey()}`)return;state.compatibility=result;state.compatKey=key;}catch(e){if(revision!==compatRevision)return;state.compatibility={compatible:false,reason:e.message};}syncCompatibility();}
async function prepareWork(){const w=state.work;if(!w?.ready||w.encoding||w.encodeError||state.codeDraft!==null)return;let entry;if(dirty()||!w.savedId||state.library.find(e=>e.id===w.savedId)?.format==='original')entry=await saveWorking();else entry=state.library.find(e=>e.id===w.savedId);if(!entry)return;state.prepared=entry.id;state.compatibility=null;state.compatKey='';navigate('connection');await pollGame();await checkCompatibility();}
async function gameAction(action){if(!state.game?.ready||state.gameBusy)return;if(action==='apply'&&!canApply())return;state.gameBusy=true;clearTimeout(pollTimer);const expected=expectedTarget(),id=state.prepared;state.gameMessage='';renderConnection();try{if(action==='read'){const result=await api.gameRead();if(result.ready===false)throw new Error(result.message||t('failed'));const dna=result.dna||result.text||result.originalDna;if(!dna)throw new Error(t('requiredDna'));showNew(dna,{name:result.name||state.game.name});}else if(action==='copy'){await api.gameCopy();toast('copied');}else{const result=action==='apply'?await api.libraryApply({id,expectedTarget:expected}):await api.gamePaste(expected);if(result.ready===false)throw new Error(result.message||t('failed'));state.gameMessage=result.message||'gameApplied';state.compatibility=null;state.compatKey='';}}catch(e){state.gameMessage=e.message;toast(e.message,true);}finally{state.gameBusy=false;if(state.page==='connection'){renderConnection();pollTimer=setTimeout(pollGame,800);}}}
async function updatePaths(kind){if(state.pathsBusy)return;state.pathsBusy=true;renderSettings();try{const paths=kind==='reset'?await api.resetPaths():await api.choosePath(kind);if(!paths)return;state.paths=paths;state.schemas=await api.getSchemas();paletteCache.clear();state.compatibility=null;state.compatKey='';compatRevision++;if(state.work){state.work.ready=false;state.work.encodeError=t('geneUnavailable');}toast('refreshed');}finally{state.pathsBusy=false;renderSettings();}}
async function onAction(node){const action=node.dataset.action,id=node.dataset.id;
 if(action==='confirm-no'||action==='confirm-yes'){$('confirmDialog').close();const resolve=confirmResolve;confirmResolve=null;resolve?.(action==='confirm-yes');return;}
 if(state.busy)return;
 if(action==='close-new'){$('newDialog').close();newDraft=null;detectRevision++;clearTimeout(detectTimer);return;}
 if(action==='navigate'){navigate(node.dataset.page);return;}
 if(action==='browse'){navigate('library');return;}
 if(action==='new'){showNew();return;}
 if(action==='edit-view'){state.view=node.dataset.view;renderEditor();return;}
 if(action==='expand-genes'||action==='collapse-genes'){geneEditSession=null;for(const group of document.querySelectorAll('.gene-group')){group.open=action==='expand-genes';if(group.open)closedGeneGroups.delete(group.dataset.geneCategory);else closedGeneGroups.add(group.dataset.geneCategory);}return;}
 if(action==='close-palette'){$('paletteDialog')?.close();paletteState=null;return;}
 if(action==='apply-palette'){applyPalette();return;}
 if(action==='palette-allele'){if(paletteState){paletteState.allele=Number(node.dataset.allele);renderPalette();}return;}
 if(action==='code-source'){state.codeSource=node.dataset.source;renderEditor();return;}
 if(action==='select-entry'){state.selected=id;renderLibrary();return;}
 if(action==='clear-filters'){Object.assign(state,{search:'',profile:'all',sex:'all',favorites:false});renderLibrary();return;}
 if(action==='undo'||action==='redo'){undo(action==='redo');return;}
 if(action==='discard-code'){state.codeDraft=null;renderEditor();return;}
 if(action==='remove-portrait'){if(node.dataset.target==='new'&&newDraft){newDraft.portrait=null;renderNew();}else if(state.work){state.work.portrait=null;state.work.dirty=true;state.work.portraitChanged=true;renderEditor();}return;}
 await run(async()=>{
  if(action==='choose-palette')await openPalette(node.dataset.gene,Number(node.dataset.allele));
  else if(action==='open-new')await openNew();
  else if(action==='archive-new')await archiveNew();
  else if(action==='create-new')await createNew();
  else if(action==='new-file'){const result=await api.loadInputFromFile();if(result?.text!=null&&newDraft){newDraft.text=result.text;newDraft.error='';$('newDnaText').value=result.text;scheduleDetect(0);}}
  else if(action==='new-paste'){const text=api.readText?await api.readText():await navigator.clipboard.readText();if(newDraft){newDraft.text=text;$('newDnaText').value=text;scheduleDetect(0);}}
  else if(action==='open-entry')await loadEntry(id);
  else if(action==='open-original')await loadEntry(id,true);
  else if(action==='library-import'){const result=await api.libraryImport();if(result&&!result.canceled){if(result.firstId)state.selected=result.firstId;await refreshLibrary();toast(t('imported',{count:result.count||0}));}}
  else if(action==='library-export'){const result=await api.libraryExport();if(result&&!result.canceled)toast('exported');}
  else if(action==='export-entry'){const result=await api.libraryExportEntry(id);if(result&&!result.canceled)toast('exported');}
  else if(action==='favorite-entry'){const entry=state.library.find(e=>e.id===id);await api.libraryUpdate(id,{favorite:!entry.favorite});await refreshLibrary();}
  else if(action==='copy-entry-current'||action==='copy-entry-original'){const entry=state.library.find(e=>e.id===id);await api.copyText(action==='copy-entry-original'?(entry.originalDna||entry.dna):entry.dna);toast('copied');}
  else if(action==='duplicate-entry')await duplicateEntry(id);
  else if(action==='metadata-entry')await editMetadata(id);
  else if(action==='save-metadata'){const name=$('entryName').value.trim();if(!name)throw new Error(t('requiredName'));await api.libraryUpdate(id,{name,sex:$('entrySex').value,note:$('entryNote').value});$('confirmDialog').close();await refreshLibrary();toast('savedMetadata');}
  else if(action==='delete-entry'){const e=state.library.find(e=>e.id===id);if(await confirmAction('deleteTitle','deleteHelp','delete',{name:e.name})){await api.libraryRemove(id);portraits.delete(id);if(state.selected===id)state.selected=null;await refreshLibrary();toast('deleted');}}
  else if(action==='save-work')await saveWorking();
  else if(action==='prepare-work')await prepareWork();
  else if(action==='prepare-entry'){state.prepared=id;state.compatibility=null;state.compatKey='';navigate('connection');await checkCompatibility();}
  else if(action==='reset-gene'){const w=state.work,g=w.genes.find(g=>g.name===node.dataset.gene);pushUndo();g.values=clone(w.baseline[g.name]);w.dirty=true;state.conversion=null;w.lossReport=[];scheduleEncode(0);renderEditor();}
  else if(action==='reset-genes'){if(await confirmAction('resetTitle','resetHelp','reset')){const w=state.work;pushUndo();for(const g of w.genes)if(Object.hasOwn(w.baseline,g.name))g.values=clone(w.baseline[g.name]);w.dirty=true;state.conversion=null;w.lossReport=[];scheduleEncode(0);renderEditor();}}
  else if(action==='convert')await convertWorking();
  else if(action==='save-converted')await saveConverted();
  else if(action==='apply-code')await applyCode();
  else if(action==='copy-code'){await api.copyText($('codeEditor').value);toast('copied');}
  else if(action==='export-code')await api.saveOutputToFile({text:$('codeEditor').value,suggestedName:'character-dna.txt'});
  else if(action==='paste-portrait')await pastePortrait(node.dataset.target);
  else if(action==='portrait-entry')await choosePortrait('entry:'+id);
  else if(action==='refresh-game')await pollGame();
  else if(action==='read-game')await gameAction('read');
  else if(action==='copy-game')await gameAction('copy');
  else if(action==='apply-prepared')await gameAction('apply');
  else if(action==='apply-clipboard')await gameAction('clipboard');
  else if(action==='choose-path')await updatePaths(node.dataset.kind);
  else if(action==='reset-paths')await updatePaths('reset');
 });
}
document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(node){if(node.closest('.context-menu'))closeContextMenu();onAction(node).catch(e=>toast(e.message,true));return;}const drop=event.target.closest('[data-portrait-target]');if(drop)run(()=>choosePortrait(drop.dataset.portraitTarget));});
document.addEventListener('input',event=>{if(state.busy)return;const node=event.target;
 if(node.dataset.paletteCoord){updatePaletteCoordinate(node);return;}
 if(node.dataset.gene&&node.dataset.index!==undefined){updateGene(node);return;}
 if(node.id==='newDnaText'&&newDraft){newDraft.text=node.value;scheduleDetect();}
 else if(node.id==='newName'&&newDraft){newDraft.name=node.value;if(newDraft.error==='requiredName'){newDraft.error='';refreshDetection();}}
 else if(node.id==='newNote'&&newDraft)newDraft.note=node.value;
 else if(node.id==='librarySearch'){const start=node.selectionStart,end=node.selectionEnd;state.search=node.value;renderLibrary();$('librarySearch').focus();$('librarySearch').setSelectionRange(start,end);}
 else if(node.id==='geneSearch'){state.geneSearch=node.value;$('geneResults').innerHTML=geneResults(state.work);}
 else if(node.id==='workName'&&state.work){state.work.name=node.value;state.work.dirty=true;document.querySelector('.workspace-name h2').textContent=node.value;updateEditorActions();}
 else if(node.id==='workNote'&&state.work){state.work.note=node.value;state.work.dirty=true;updateEditorActions();}
 else if(node.id==='codeEditor'&&state.codeSource==='current'){state.codeDraft=node.value===currentCodeText(state.work)?null:node.value;$('codeStatus').textContent=t(state.codeDraft!==null?'codeDirty':'working');for(const key of ['apply-code','discard-code'])document.querySelector(`[data-action="${key}"]`).disabled=state.codeDraft===null;updateEditorActions();}
});
document.addEventListener('change',event=>{if(state.busy)return;const n=event.target;if(n.dataset.gene)return;
 if(n.id==='paletteBoth'){if(paletteState)paletteState.both=n.checked;return;}
 const id=n.id;
 if(id==='languageSelect'){run(async()=>{const previous=window.I18n.language;try{await api.setLanguage(n.value);window.I18n.setLanguage(n.value);render();if(newDraft)renderNew();}catch(e){window.I18n.setLanguage(previous);render();throw e;}});}
 else if(id==='codeFormat'){if(state.codeDraft!==null){n.value=state.codeFormat;toast('finishCodeFirst');}else{state.codeFormat=n.value;renderEditor();}}
 else if(id==='newProfile'&&newDraft){newDraft.profile=n.value;scheduleDetect(0);}
 else if(id==='newSex'&&newDraft)newDraft.sex=n.value;
 else if(id==='libraryProfile'){state.profile=n.value;renderLibrary();}
 else if(id==='librarySex'){state.sex=n.value;renderLibrary();}
 else if(id==='libraryFavorites'){state.favorites=n.checked;renderLibrary();}
 else if(id==='librarySort'){state.sort=n.value;renderLibrary();}
 else if(id==='geneCategory'){state.category=n.value;$('geneResults').innerHTML=geneResults(state.work);}
 else if(id==='geneChanged'){state.changed=n.checked;$('geneResults').innerHTML=geneResults(state.work);}
 else if(id==='geneUnknown'){state.unknown=n.checked;$('geneResults').innerHTML=geneResults(state.work);}
 else if(id==='workSex'&&state.work){state.work.sex=n.value;state.work.dirty=true;updateEditorActions();}
 else if(id==='convertTarget'||id==='convertFormat'||id==='convertLossy'){if(id==='convertTarget')state.target=n.value;if(id==='convertFormat')state.targetFormat=n.value;if(id==='convertLossy')state.lossy=n.checked;state.conversion=null;if($('conversionResult'))$('conversionResult').innerHTML='';}
 else if(id==='preparedSelect'){state.prepared=n.value;checkCompatibility();}
 else if(id==='portraitFile'){const file=n.files[0];run(()=>stagePortrait(file,portraitTarget));n.value='';}
});
document.addEventListener('dragover',event=>{const zone=event.target.closest('[data-portrait-target]');if(zone){event.preventDefault();zone.classList.add('dragging');}});
document.addEventListener('dragleave',event=>{const zone=event.target.closest('[data-portrait-target]');if(zone&&!zone.contains(event.relatedTarget))zone.classList.remove('dragging');});
document.addEventListener('drop',event=>{if(state.busy){event.preventDefault();return;}const zone=event.target.closest('[data-portrait-target]');if(!zone)return;event.preventDefault();zone.classList.remove('dragging');const file=Array.from(event.dataTransfer.files).find(f=>f.type.startsWith('image/'));if(file)run(()=>stagePortrait(file,zone.dataset.portraitTarget));});
document.addEventListener('paste',event=>{if(state.busy){event.preventDefault();return;}const files=Array.from(event.clipboardData?.items||[]).filter(item=>item.type.startsWith('image/'));if(!files.length)return;const target=$('newDialog').open?'new':event.target.closest('[data-portrait-target]')?.dataset.portraitTarget||(state.page==='edit'&&state.work?'work':state.page==='library'&&state.selected?'entry:'+state.selected:null);if(!target)return;event.preventDefault();run(()=>stagePortrait(files[0].getAsFile(),target));});
document.addEventListener('keydown',event=>{if(state.busy&&!event.target.closest('#confirmDialog')){event.preventDefault();return;}const zone=event.target.closest('[data-portrait-target]');if(zone&&(event.key==='Enter'||event.key===' ')){event.preventDefault();run(()=>choosePortrait(zone.dataset.portraitTarget));return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&state.work&&!$('newDialog').open&&!$('paletteDialog')?.open){event.preventDefault();run(saveWorking);}if((event.ctrlKey||event.metaKey)&&!event.target.closest('input,textarea,select')&&state.page==='edit'){if(event.key.toLowerCase()==='z'){event.preventDefault();undo(event.shiftKey);}if(event.key.toLowerCase()==='y'){event.preventDefault();undo(true);}}});
$('newDialog').addEventListener('cancel',event=>{if(state.busy){event.preventDefault();return;}newDraft=null;detectRevision++;clearTimeout(detectTimer);});
$('confirmDialog').addEventListener('cancel',()=>{const resolve=confirmResolve;confirmResolve=null;resolve?.(false);});
document.addEventListener('contextmenu',event=>{if(state.busy){event.preventDefault();return;}const tile=event.target.closest('.character-tile');if(tile){event.preventDefault();showContextMenu(tile.dataset.id,event.clientX,event.clientY);}});
document.addEventListener('pointerdown',event=>{if(contextMenu&&!contextMenu.contains(event.target))closeContextMenu();});
document.addEventListener('keydown',event=>{if(state.busy)return;if(contextMenu){if(event.key==='Escape'||event.key==='Tab'){closeContextMenu();return;}if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const buttons=[...contextMenu.querySelectorAll('button:not(:disabled)')];const index=buttons.indexOf(document.activeElement);buttons[event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();return;}}const tile=event.target.closest('.character-tile');if(tile&&(event.key==='ContextMenu'||event.shiftKey&&event.key==='F10')){event.preventDefault();const bounds=tile.getBoundingClientRect();showContextMenu(tile.dataset.id,bounds.left+20,bounds.top+20);}});
document.addEventListener('focusout',event=>{if(geneEditSession?.node===event.target)geneEditSession=null;});
document.addEventListener('pointerdown',event=>{if(event.target.matches('input[type=range][data-gene]'))geneEditSession=null;});
document.addEventListener('pointerup',()=>{if(geneEditSession?.node?.type==='range')geneEditSession=null;});
document.addEventListener('toggle',event=>{const group=event.target;if(!group.matches?.('.gene-group')||state.geneSearch)return;if(group.open)closedGeneGroups.delete(group.dataset.geneCategory);else closedGeneGroups.add(group.dataset.geneCategory);},true);
async function initialize(){try{window.I18n.setLanguage(await api.getLanguage());}catch{window.I18n.setLanguage('en');}render();const results=await Promise.allSettled([api.libraryList(),api.getSchemas(),api.getPaths(),api.getVersion()]);if(results[0].status==='fulfilled')state.library=results[0].value;else toast(results[0].reason.message,true);if(results[1].status==='fulfilled')state.schemas=results[1].value;if(results[2].status==='fulfilled')state.paths=results[2].value;if(results[3].status==='fulfilled')state.version=results[3].value;render();}
initialize().catch(e=>toast(e.message,true));
